"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Get products table schema
const schema = db.prepare(\"PRAGMA table_info('products')\").all();
console.log('=== Products Schema ===');
schema.forEach(c => console.log(c.name, c.type));

console.log();

// Find the product
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-73FAB4'\").get();
console.log('=== Product PROD-73FAB4 ===');
console.log(JSON.stringify(product, null, 2));
"
